from __future__ import annotations

import hashlib
import json
import os
import secrets
import sqlite3
import uuid
from contextlib import closing, contextmanager
from datetime import datetime, timedelta, timezone
from pathlib import Path, PurePosixPath
from typing import Any, Iterator

from . import SCHEMA_VERSION


ALLOWED_JOB_TYPES = {
    "feature_batch",
    "lightgbm_train",
    "qlib_train",
    "vectorized_screen",
    "statistical_precompute",
    "alphasage_smoke",
    "alphasage_mine",
    "alphagen_mine",
    "torch_model_train",
    "representation_train",
}

FORBIDDEN_JOB_TYPES = {
    "live_trade",
    "paper_order_execution",
    "credential_rotation",
    "exchange_account_access",
    "k3_verdict",
    "dsr_verdict",
